/// <summary>
/// <c>METCommonReportContract</c> class is a contract class used to run the common reports
/// </summary>
[DataContractAttribute]
public class METCommonReportContract
{
    MetLoadId   metLoadId;
    RecId recId;

}

Method.Source:
/// <summary>
/// parm method to get or set RecordId
/// </summary>
/// <param name = "_recId">RecId</param>
/// <returns>RecId</returns>
[DataMemberAttribute('recId')]
public RecId parmRecId(RecId _recId = RecId)
{
    recId = _recId;
    return recId;
}

/// <summary>
/// Parameter method for bundling logic Id
/// </summary>
/// <param name = "_metLoadId">Load Id reference</param>
/// <returns>MetLoadId reference</returns>
[DataMemberAttribute('loadId'),
SysOperationControlVisibilityAttribute(false)]
public MetLoadId parmBundleLoadId(MetLoadId _metLoadId = metLoadId)
{
    metLoadId = _metLoadId;
    return metLoadId;
}
